import { useRef, useState } from 'react';
import { Button, Input, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [isDone, setIsDone] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (email.trim() === '') return;
    setEmail('');
    setIsDone(true);
    inputRef.current?.focus();
  };

  return (
    <>
      <form className="jx-stack" onSubmit={handleSubmit} noValidate={false}>
        <label className="jx-label" htmlFor="newsletter-email">
          Электронная почта
        </label>
        <Input
          id="newsletter-email"
          ref={inputRef}
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="you@example.com"
          value={email}
          onChange={(event) => {
            setEmail(event.currentTarget.value);
            setIsDone(false);
          }}
        />
        <Button type="submit">Подписаться</Button>
      </form>

      <div
        aria-live="polite"
        style={{
          position: 'fixed',
          insetInlineEnd: 'var(--jx-space-4)',
          insetBlockEnd: 'var(--jx-space-4)',
          zIndex: 'var(--jx-z-toast)',
        }}
      >
        {isDone ? (
          <Toast
            title="Готово"
            description="Мы отправили письмо на указанный адрес."
            onClose={() => setIsDone(false)}
          />
        ) : null}
      </div>
    </>
  );
}

